rows.forEach((r, i) => {
  ['A','B','C','D'].forEach(c => {
    const s = src.getRange(`${c}${r}`);
    const d = dst.getRange(`${c}${i+1}`);
    const v = s.getValue();
    d.setValue(typeof v === 'string' ? "'" + v : v);
    d.getStyle().setNumberFormat(s.getStyle().getNumberFormat());
  });
});
